import {comparisonMetrics,viewSummary,medianViews,viewSubscriberRatio,viewWindowLabel,nicheEvidence,nicheLabel,countryName,countrySource,contentLanguage} from './research-core.js';
import {markets,languages,defaults,niches,localizedQuery,evidence,factorLabels,defaultWeights,fitReason,unknowns,angle,shortlistCSV} from './research-core.js';
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const numeric=v=>v==null?'Unknown':Number(v).toLocaleString('en-GB',{maximumFractionDigits:1});
const url=v=>{try{const u=new URL(v);return ['https:','http:'].includes(u.protocol)&&!u.username&&!u.password?esc(u.href):'#'}catch{return '#'}};
const link=(href,title)=>`<a href="${url(href)}" target="_blank" rel="noopener noreferrer">${esc(title)} ↗</a>`;
const opts=(obj,current)=>Object.entries(obj).map(([v,l])=>`<option value="${esc(v)}" ${v===current?'selected':''}>${esc(l)}</option>`).join('');
const sizes={all:'All sizes · evidence fit',nano:'Nano · under 10k',micro:'Micro · 10k–100k',mid:'Mid · 100k–500k',large:'Large · 500k+'};
let csvDraft='';
let busy=false,error='',status=null,resultNote='',nextToken='',requestConfig=null,comments={},comparison=[],showCompare=false;
function cfg(state){state.research??={language:'fi',niche:'Budget gaming',size:'all',goal:state.campaign.goal,source:'live',query:'',ids:[]};state.research.market??=Object.entries(defaults).find(([,language])=>language===state.research.language)?.[0]||'FI';state.research.mode??='video';state.research.minSubscribers=Math.max(800,state.research.minSubscribers||800);state.research.maxSubscribers??=0;state.research.sort??='views';state.research.minAverageViews??=0;state.researchWeights??={...defaultWeights};state.researchWeights.language=0;state.records??={};return state.research;}
export function filtered(state){
 const q=cfg(state);
 return Object.values(state.records)
 .filter(c=>c.sourceType===q.source&&(q.source!=='live'||q.ids.includes(c.id)&&c.market===q.market&&c.country===q.market))
 .filter(c=>!c.country||countryName(c)===(markets[q.market]||q.market))
 .filter(c=>{if(q.size==='all')return true;const n=c.followers;if(n==null)return false;return q.size==='nano'?n<10000:q.size==='micro'?n>=10000&&n<100000:q.size==='mid'?n>=100000&&n<500000:n>=500000})
 .filter(c=>{const e=evidence(c,q,state.researchWeights);return e.factors.language===100&&e.relevant.length>0&&(c.followers!=null&&c.followers>=q.minSubscribers&&(q.maxSubscribers===0||c.followers<=q.maxSubscribers))&&(q.minAverageViews===0||e.avg!=null&&e.avg>q.minAverageViews)})
 .sort((a,b)=>(q.sort==='views'?(viewSummary(b).average??-1)-(viewSummary(a).average??-1):q.sort==='subscribers'?(b.followers??-1)-(a.followers??-1):0)||(evidence(b,q,state.researchWeights).score??-1)-(evidence(a,q,state.researchWeights).score??-1));
}
function contactHTML(c){return c.contact?`${esc(c.contact.kind)}: ${c.contact.kind==='Public contact link'?link(c.contact.value,c.contact.value):esc(c.contact.value)} · ${link(c.contact.sourceUrl,'Source')}`:'No public contact found'}
function sponsorFields(c){return `<div class="sponsor-facts"><p><b>Channel / creator country:</b> ${esc(countryName(c))} <small>(${esc(countrySource(c))})</small><br><b>Target search market:</b> ${esc(markets[c.market]||c.market||'Unknown')} · <b>Content language:</b> ${esc(contentLanguage(c))}<br><b>Verified audience country:</b> Unknown</p><p><b>Niche / games / hardware:</b> ${esc(nicheLabel(c))}</p><p><b>Public contact:</b> ${contactHTML(c)}</p></div>`}
function ratioBadge(c){const ratio=viewSubscriberRatio(c);return `<span class="view-ratio ${ratio.tone}">${esc(ratio.text)}${ratio.label?` · ${esc(ratio.label)}`:''}</span>`}
function medianLabel(c){const median=medianViews(c);return `<span class="median-views">Median: ${median===null?'N/A':numeric(median)+' views'}</span>`}
function tag(c){return c.sourceType==='live'?'YOUTUBE API':'CSV IMPORT · UNVERIFIED'}
function card(c,state){const q=cfg(state),e=evidence(c,q,state.researchWeights),p=state.pipeline[c.id];return `<article class="card"><div class="row"><span class="pill ${c.sourceType==='live'?'lime':''}">${tag(c)}</span><label class="check"><input type="checkbox" data-rcompare="${esc(c.id)}" ${comparison.includes(c.id)?'checked':''}>Compare</label></div><div><h3>${esc(c.name)}</h3><small>${esc(c.platform)} · ${c.followers==null?'Size unknown':c.followers<10000?'Nano creator':c.followers<100000?'Micro creator':'Mid / large creator'}</small></div><div class="metrics"><div><strong>${numeric(c.followers)}</strong><small>Subscribers / followers</small></div><div><strong>${numeric(e.avg)}</strong><small>Recent average views</small>${medianLabel(c)}${ratioBadge(c)}</div><div><strong>${e.score??'—'}/100</strong><small>Evidence fit · ${e.known}/5</small></div></div><small>${esc(viewWindowLabel(c))}<br>Last checked: ${esc(viewSummary(c).checkedAt||'Unknown')}</small>${sponsorFields(c)}<p class="reason">${esc(fitReason(c,q,e))}</p><small>${c.audienceCountry&&c.audienceSource?'Audience claim: uploader-supplied evidence':'Audience geography unverified'}</small><button data-rdetail="${esc(c.id)}">Review evidence →</button><button data-rsave="${esc(c.id)}">${p?'✓ '+esc(p.review||'Shortlisted'):'＋ Save to shortlist'}</button></article>`}
export function researchHTML(state){const q=cfg(state),list=filtered(state),query=q.query||localizedQuery(q);return `<div class="head"><div><div class="eyebrow">Discovery / beyond follower count</div><h1>Find the overlooked voices.</h1><p class="muted">Local-language discovery. Observable evidence. A shortlist you can act on.</p></div><button data-nav="pipeline">Open shortlist →</button></div><div class="source-tabs"><button data-source="live" class="${q.source==='live'?'dark':''}">YouTube API</button><button data-source="imported" class="${q.source==='imported'?'dark':''}">CSV imports</button><button data-nav="discover">Demo examples ↗</button></div><div class="banner">${q.source==='live'?'Live-source workspace. No sample creators appear here.':'Imported records retain their source and uploader provenance. They are not API-verified.'} Search up to 200 unique channels through native-language queries, then check declared country, recent language evidence and niche fit. Audio language takes priority over title language. Missing or contradictory evidence is excluded. Audience geography remains unverified. Sort the qualifying creators by recent average views, subscribers or evidence fit; retrieval always uses relevance.</div><section class="panel"><form id="research-form"><fieldset ${busy?'disabled':''}><div class="research-fields"><label>Search by<select id="r-mode">${opts({channel:'Channels',video:'Recent videos'},q.mode)}</select></label><label>Target country / market<select id="r-market">${opts(markets,q.market)}</select></label><label>Search language<select id="r-language">${opts(languages,q.language)}</select></label><label>Niche<select id="r-niche">${opts(Object.fromEntries(niches.map(n=>[n,n])),q.niche)}</select></label><label>Creator size<select id="r-size">${opts(sizes,q.size)}</select></label><label>Minimum subscribers<input id="r-minSubscribers" type="number" min="800" step="1" required value="${q.minSubscribers}"></label><label>Maximum subscribers (0 = no cap)<input id="r-maxSubscribers" type="number" min="0" step="1" required value="${q.maxSubscribers}"></label><label>Sort by<select id="r-sort">${opts({views:'Highest recent average views',subscribers:'Most subscribers',fit:'Best evidence fit'},q.sort)}</select></label><label>Average views greater than<input id="r-minAverageViews" type="number" min="0" step="1" required value="${q.minAverageViews}"></label></div><small>Strict language evidence and niche keywords are required. At least 800 subscribers are required. Average-view filtering starts disabled for new workspaces; saved limits are preserved. The subscriber cap is inclusive; 0 disables the cap or minimum-view limit. Unknown subscriber counts are excluded. Prenew’s typical collaboration sizes are guidance, not eligibility rules. Limits apply immediately to loaded results. Lowering them requires a new search to recover excluded candidates.</small><label style="margin-top:18px">Localized search terms<input id="r-query" maxlength="220" value="${esc(query)}" required></label><small>Suggested: ${esc(localizedQuery(q))}. Separate up to eight query alternatives with |. Each is searched independently and duplicate channels are merged. Editable before searching.</small><div class="actions"><button class="primary" type="submit">${busy?'Retrieving public evidence…':'Search YouTube'}</button><button type="button" id="reset-query">Use localized suggestion</button><button type="button" id="local-preset">Local discovery preset</button></div></fieldset></form><p class="muted" id="api-status">${status===null?'Checking local API setup…':status.youtubeConfigured?'YouTube key configured on server.':'YouTube key missing. Add YOUTUBE_API_KEY to .env and restart python3 server.py.'} One search collects up to 200 unique channels before filters, using 50 matches per page and at most 12 search pages. It may return fewer when results or the request budget run out. Up to 50 latest uploads per eligible channel support the 30/90-day view statistics. Responses are cached for 30 minutes.</p></section>${q.source==='imported'?`<section class="panel" style="margin-top:18px"><h2>Bring your own creator evidence.</h2><p class="muted">Twitch, TikTok, Instagram and YouTube · UTF-8 CSV · max 500 rows / 1 MB. Blank metrics stay unknown. Source URL and provenance are required. Same-source duplicates update the existing record.</p><a href="/creator-template.csv" download>Download CSV header template</a><label style="margin-top:16px">Import creator CSV<input id="csv-file" type="file" accept=".csv,text/csv" ${busy?'disabled':''}></label><label>Or paste CSV<textarea id="csv-text" placeholder="name,platform,source_url,provenance,…">${esc(csvDraft)}</textarea></label><button id="csv-paste" ${busy?'disabled':''}>Validate & import pasted CSV</button></section>`:''}<div id="research-error" role="alert">${error?`<div class="error">${esc(error)}</div>`:''}</div><section class="panel" style="margin-top:18px"><h2>How community engagement is calculated</h2><p>Per-video engagement (%) = (likes + comments) / views × 100. We average these percentages equally across eligible recent uploads (last 90 days) with positive views and known likes and comments.</p><p>Engagement score = min(100, round(average engagement % × 20)). Example: 200 likes + 50 comments on 10,000 views = 2.5%, or 50/100. Missing metrics are excluded; no eligible sample means Unknown. This is a public interaction proxy: it does not assess comment substance, genuine community, Discord activity or buying intent.</p></section><details class="panel" style="margin-top:18px"><summary>How evidence fit is ranked · adjustable weights</summary><p class="muted">A triage heuristic, never a trust score or prediction of sales. Unknown factors are excluded and coverage is shown. Language is a required evidence check, not a ranking factor.</p>${Object.entries(factorLabels).filter(([k])=>k!=='language').map(([k,l])=>`<label class="weight">${l}<input type="range" data-rweight="${k}" min="0" max="100" value="${state.researchWeights[k]}"><span>${state.researchWeights[k]}</span></label>`).join('')}<p class="muted">Topic = share of sampled uploads published in the last 90 days whose titles/descriptions match niche or seller keywords. Search-only hits do not establish current niche fit. Niche and game labels come from recent titles and link to their evidence. For live candidates, inspect up to five latest uploads: at least three inspected, two matching effective languages and no conflict. Audio language takes priority; title/description language is a fallback when audio metadata is missing. Channel-title language does not override video evidence. Missing evidence is excluded; titles and descriptions remain available for manual review. Recency = 100 within 30 days / 70 within 90 / 40 within 180 / 10 older. Views = measured recent average views ÷ subscribers × 100, capped at 100. Engagement = mean (likes + comments) ÷ views × 100, scaled × 20 and capped at 100. These public metrics cannot establish honesty, audience demographics or genuine engagement. Shorts, streams and long videos are not normalized.</p></details><div class="row"><h2>${list.length} ${q.source==='live'?'YouTube candidates':'imported candidates'}</h2></div><p class="muted discovery-funnel">${esc(resultNote)}${q.source==='live'&&q.ids.length?' '+q.ids.map(id=>state.records[id]).filter(c=>c&&evidence(c,q,state.researchWeights).relevant.length===0).length+' loaded creators excluded by current niche; '+list.length+' displayed after current filters.':''}</p>${q.source==='live'&&requestConfig?`<p class="muted">Last search attempt: ${esc(markets[requestConfig.market])} / ${esc(languages[requestConfig.language])} · ${esc(requestConfig.query)}. Changing filters does not run a new search.</p>`:''}${showCompare?compareHTML(state):''}<div class="grid">${list.map(c=>card(c,state)).join('')}</div>${!list.length?`<div class="panel empty"><h2>${q.source==='live'?'Start with a local-language search.':'Import your first sourced creators.'}</h2><p class="muted">${q.source==='live'?'Choose a market and language, then search. Try the Local discovery preset to search recent videos with the view limit disabled. Add native query alternatives when eligible results are sparse. A missing key, empty response or failed request will never be replaced by demo data.':'Use the CSV template to bring in real records you can substantiate. There are no preloaded imported identities.'}</p></div>`:''}<div class="actions">${nextToken&&q.source==='live'?`<button id="next-page" ${busy?'disabled':''}>Load next result page</button>`:''}${comparison.length?`<button id="rcompare-show">${showCompare?'Hide':'Show'} comparison (${comparison.length}/3)</button>`:''}</div>`}
function compareHTML(state){
 const cs=comparison.map(id=>state.records[id]).filter(Boolean),metrics=new Map(cs.map(c=>[c.id,comparisonMetrics(c)]));
 const avg=(c,key)=>{const m=metrics.get(c.id)[key];return m.value===null?'Unknown':`${numeric(Math.round(m.value*10)/10)} (${m.count} videos)`};
 const rows=[['Name',c=>c.name],['Platform / source',c=>c.platform+' / '+tag(c)],['Followers / subscribers',c=>numeric(c.followers)],['Country / source',c=>countryName(c)+' / '+countrySource(c)],['Target search market',c=>markets[c.market]||'Unknown'],['Content language',contentLanguage],['Verified audience country',()=> 'Unknown'],['Niche / game / hardware',nicheLabel],['Public contact',c=>c.contact?.value||'No public contact found'],['Recent average views',c=>avg(c,'views')],['Recent median views',c=>{const median=medianViews(c);return median===null?'Unknown':numeric(median)}],['Views window / sample',viewWindowLabel],['Last checked',c=>viewSummary(c).checkedAt||'Unknown'],['Average comments',c=>avg(c,'comments')],['Average likes',c=>avg(c,'likes')],['Engagement rate',c=>{const m=metrics.get(c.id);return m.engagement===null?'Unknown':`${m.engagement.toFixed(2)}% (${m.engagementSamples} videos)`}],['Views per follower',c=>{const m=metrics.get(c.id);return m.views.value!==null&&c.followers>0?(m.views.value/c.followers*100).toFixed(1)+'%':'Unknown'}],['Prenew content themes',c=>metrics.get(c.id).themes.join(' · ')||'No matching themes found'],['Keywords found in titles / descriptions',c=>metrics.get(c.id).keywords.slice(0,24).join(', ')||'No matching keywords found'],['Evidence sample',c=>metrics.get(c.id).total+' supplied videos']];
 return `<div class="panel tablewrap"><h2>Compare creators for Prenew</h2><p class="muted">Recent views use the 30-day publication window, with a 90-day fallback and a minimum of three measured uploads. Likes, comments and engagement use supplied evidence videos with known metrics; sample counts are shown. Engagement is the average of (likes + comments) ÷ views per video. Keywords are observed in titles and descriptions, not verified endorsements. Search-only matches do not enter the view average; Shorts, streams and long videos are not normalized.</p><table><thead><tr><th>Metric</th>${cs.map(c=>`<th>${link(c.sourceUrl,c.name)}</th>`).join('')}</tr></thead><tbody>${rows.map(([label,value])=>`<tr><th>${esc(label)}</th>${cs.map(c=>`<td style="white-space:normal;min-width:180px">${esc(value(c))}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
export function researchDetailHTML(c,state){const q=cfg(state),e=evidence(c,q,state.researchWeights),p=state.pipeline[c.id],videos=c.videos||[];return `<button data-nav="research" class="back">← Back to discovery</button><div class="head"><div><span class="pill lime">${tag(c)}</span><h1>${esc(c.name)}</h1><p>${link(c.sourceUrl,'Open creator on '+c.platform)}</p></div><button data-rsave="${esc(c.id)}" class="primary">${p?'✓ Saved to shortlist':'＋ Save to shortlist'}</button></div><div class="banner">${esc(c.source)} · ${c.sourceType==='live'?'API retrieval':'Import'}: ${esc(c.fetchedAt)}${c.importFile?' · File: '+esc(c.importFile):''}<br>Discovery market: ${esc(markets[c.market]||c.market||'Not supplied')}. ${c.audienceCountry&&c.audienceSource?'Audience claim supplied by uploader: '+esc(c.audienceCountry)+'. '+link(c.audienceSource,'Inspect audience source'):'Audience geography unverified.'}</div><div class="layout"><div class="stack"><section class="panel"><div class="row"><h2>Why they may fit Prenew</h2><strong class="score">${e.score??'—'}/100</strong></div><p>${esc(fitReason(c,q,e))}</p>${Object.entries(e.factors).map(([k,v])=>`<div class="row"><span>${factorLabels[k]}</span><b>${v===null?'Unknown':v+'/100'}</b></div><div class="bar"><i style="width:${v??0}%"></i></div>`).join('')}<small>${e.known}/5 factors known. Ranked for ${esc(q.niche)} / ${esc(q.goal)} / ${esc(languages[q.language])}; metadata clues are not independently verified. Public engagement ${e.rate===null?'unknown':numeric(e.rate)+'% over '+e.engagementSamples+' videos'}.</small></section><section class="panel"><h2>Creator facts & recent views</h2>${sponsorFields(c)}<div class="metrics"><div><strong>${numeric(c.followers)}</strong><small>Subscribers / followers</small></div><div><strong>${numeric(e.avg)}</strong><small>Recent average views</small>${medianLabel(c)}${ratioBadge(c)}</div></div><p>${esc(viewWindowLabel(c))}<br>Last checked: ${esc(viewSummary(c).checkedAt||'Unknown')}</p><p class="muted">${esc(viewSummary(c).method)} ${viewSummary(c).sampleLimited?'The channel has more uploads: this is a capped sample, not every video in the window.':''}</p><h3>Language evidence</h3><p>${esc(c.languageEvidence?c.languageEvidence.positiveVideos+'/'+c.languageEvidence.sampleSize+' latest uploads match. '+c.languageEvidence.method:'Uploader-supplied evidence; not independently verified.')}</p><h3>Niche / game evidence</h3>${nicheEvidence(c).map(x=>`<p><b>${esc(x.label)}:</b> ${x.videos.slice(0,2).map(video=>link(video.url,video.title)).join(' · ')}</p>`).join('')||'<p>Unknown</p>'}<h2>Recent content evidence</h2><p class="muted">${c.sourceType==='live'?'Videos that matched your search, then up to 50 latest public uploads. Only marked uploads enter the recent view average. Unknown language metadata is never inferred from an English game title.':'Video evidence supplied by the CSV uploader; check the source yourself.'} Titles and descriptions support keyword matches; the app has not watched these videos.</p>${videos.length?videos.map(v=>`<article class="video-evidence">${v.matchedSearch?'<span class="pill lime">MATCHED YOUR SEARCH</span> ':''}${viewSummary(c).videoIds.includes(v.id)?'<span class="pill">VIEW WINDOW SAMPLE</span> ':''}<span class="pill">${e.relevant.includes(v)?'KEYWORD MATCH':'OTHER EVIDENCE'}</span><h3>${link(v.url,v.title)}</h3><small>${esc(v.publishedAt||'Date unknown')} · audio language: ${esc(v.audioLanguage||'Unknown')} · metadata language: ${esc(v.metadataLanguage||v.language||'Unknown')}</small><p class="muted">${esc((v.description||'No description supplied.').slice(0,350))}</p><div class="row"><span>${numeric(v.views)} views</span><span>${numeric(v.likes)} likes</span><span>${numeric(v.comments)} comments</span></div>${c.sourceType==='live'&&v.id?`<button data-comments="${esc(v.id)}" style="margin-top:12px">Inspect public audience questions</button><div>${comments[v.id]?esc(comments[v.id].error||comments[v.id].note):''}${(comments[v.id]?.comments||[]).map(x=>`<blockquote>${esc(x.text)}<br>${link(x.url,'View original question')} · ${esc(x.publishedAt)}</blockquote>`).join('')}</div>`:''}</article>`).join(''):'<p>No recent video evidence supplied. Do not infer fit from follower count alone.</p>'}</section></div><div class="stack"><section class="panel"><span class="eyebrow">Human trust review</span><h2>Inspect the claims. Keep the nuance.</h2><p class="muted">Hypotheses for manual review, not automated trust judgments. Likes alone cannot establish trust.</p><ul><li>Performance honesty: does a linked video show test settings, hardware and measured results?</li><li>Trade-offs: does it explain condition, limitations, noise, upgradeability and price comparisons?</li><li>Audience questions: are comments asking substantive questions about hardware or purchase decisions?</li><li>Disclosure: check sponsorships, competing retailers and whether criticism remains independent.</li></ul><p><b>Automated finding:</b> not assessed. Watch the source content before recording a judgment.</p></section><section class="panel"><h2>What remains unknown</h2><ul>${unknowns(c).map(x=>`<li>${esc(x)}</li>`).join('')}</ul><h3>Possible collaboration angle</h3><p>${esc(angle(c,q))}</p></section><section class="panel"><h2>Shortlist decision</h2><label>Review status<select id="review-status" data-id="${esc(c.id)}">${opts({'Unreviewed':'Unreviewed','Reviewing':'Reviewing','Accepted':'Accepted','Rejected':'Rejected'},p?.review||'Unreviewed')}</select></label><label style="margin-top:16px">Review notes<textarea id="review-notes" data-id="${esc(c.id)}" placeholder="Record evidence, limitations, conflicts and next steps…">${esc(p?.notes||'')}</textarea></label><small>Notes and decisions save locally. Accepting a candidate does not approve outreach.</small><button id="export-one" data-id="${esc(c.id)}" style="margin-top:14px">Export this candidate CSV</button></section><details class="panel"><summary>Optional editable outreach</summary><p class="muted">English draft based on supplied facts and the visible evidence. No automatic sending. Rejected candidates must be reopened before outreach approval.</p><button data-rdraft="${esc(c.id)}" ${p?.review==='Rejected'?'disabled':''}>${p?.draft?'Regenerate draft':'Create draft'}</button>${p?.draft?`<label>Outreach draft<textarea id="research-draft" data-id="${esc(c.id)}" class="outreach">${esc(p.draft)}</textarea></label><button data-rapprove="${esc(c.id)}" class="primary" ${p.approved||p.review==='Rejected'?'disabled':''}>${p.approved?'✓ Approved':'Approve draft'}</button>`:''}</details></div></div><div role="alert">${error?`<p class="error">${esc(error)}</p>`:''}</div>`}
async function api(path,options){const response=await fetch(path,options);let data;try{data=await response.json()}catch{throw Error('The API server is not running. Stop the old static server and run python3 server.py.')}if(!response.ok)throw Error(data.error||'Request failed.');return data;}
export function exportShortlist(state,creators,ids=null){const config=cfg(state);const entries=Object.entries(state.pipeline).filter(([id])=>!ids||ids.includes(id)).map(([id,pipeline])=>({creator:creators.find(c=>c.id===id),pipeline})).filter(x=>x.creator);const blob=new Blob([shortlistCSV(entries,config,state.researchWeights)],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='prenew-shortlist.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);}
function renderViewIndicators(state){
 const attach=(root,id)=>{const creator=state.records[id];if(!creator)return;const label=[...root.querySelectorAll('.metrics small')].find(el=>el.textContent.trim()==='Recent average views');if(!label)return;if(!label.parentElement.querySelector('.median-views'))label.insertAdjacentHTML('afterend',medianLabel(creator));if(!label.parentElement.querySelector('.view-ratio'))label.parentElement.insertAdjacentHTML('beforeend',ratioBadge(creator));};
 document.querySelectorAll('.card').forEach(card=>attach(card,card.querySelector('[data-rdetail]')?.dataset.rdetail));
 const detail=document.querySelector('#export-one');if(detail)attach(document,detail.dataset.id);
}
export function bindResearch(ctx){const {state,save,render,select,ensure,creators,toast}=ctx,q=cfg(state);
renderViewIndicators(state);
const refresh=()=>{save();render()};
if(status===null){status={};api('/api/status').then(data=>{status=data;const el=document.querySelector('#api-status');if(el)el.textContent=(data.youtubeConfigured?'YouTube configured. ':'YouTube key missing: add YOUTUBE_API_KEY to .env and restart python3 server.py. ')+'30-minute server cache; up to 200 unique channels per search, with a 12-page request budget. No sample fallback.'}).catch(e=>{status={};const el=document.querySelector('#api-status');if(el)el.textContent=e.message})}
document.querySelectorAll('[data-source]').forEach(b=>b.onclick=()=>{q.source=b.dataset.source;error='';resultNote='';comparison=[];showCompare=false;refresh()});
for(const field of ['minSubscribers','maxSubscribers','minAverageViews'])document.querySelector('#r-'+field)?.addEventListener('change',event=>{if(!event.target.checkValidity())return;q[field]=Number(event.target.value);nextToken='';refresh()});
for(const field of ['market','language','niche','size','mode','sort'])document.querySelector('#r-'+field)?.addEventListener('change',event=>{q[field]=event.target.value;if(field==='market')q.language=defaults[q.market];comparison=[];showCompare=false;if(!['size','sort'].includes(field))q.query='';nextToken='';refresh()});
document.querySelector('#r-query')?.addEventListener('input',e=>{q.query=e.target.value;nextToken='';save()});
document.querySelector('#reset-query')?.addEventListener('click',()=>{q.query='';nextToken='';refresh()});
document.querySelector('#local-preset')?.addEventListener('click',()=>{Object.assign(q,{mode:'video',query:'',size:'all',minSubscribers:800,maxSubscribers:0,minAverageViews:0});nextToken='';refresh();toast('Local discovery preset applied. Run Search YouTube to retrieve candidates.');});
async function search(more=false){
 if(busy)return;busy=true;error='';q.source='live';nextToken='';requestConfig={...q,query:q.query||localizedQuery(q)};refresh();
 try{
  const config=requestConfig;
  const data=await api('/api/youtube/search?'+new URLSearchParams({q:config.query,market:config.market,language:config.language,size:config.size,mode:config.mode,minSubscribers:config.minSubscribers,maxSubscribers:config.maxSubscribers,sort:config.sort,minAverageViews:config.minAverageViews}));
  for(const c of data.creators)state.records[c.id]=c;
  q.ids=[...new Set(data.creators.map(c=>c.id))];
  const f=data.funnel,d=data.discovery,x=data.excluded||{};
  q.lastFunnel={...f,...d,market:config.market,language:config.language};
  const stop={target_reached:'200-channel target reached',results_exhausted:'Available query results exhausted',request_budget:'12-page search budget reached',upstream_limit:'Search stopped by API limit'};
  resultNote=(d?d.uniqueChannels+'/'+d.targetChannels+' unique channels · '+d.searchRequests+' search pages · '+stop[d.stopReason]+'. ':'')+(f?f.matches+' matches → '+f.channels+' unique channels → '+f.subscribers+' pass subscribers → '+f.size+' pass size → '+f.country+' pass country → '+f.language+' pass language → '+f.views+' pass average views. ':'')+'Excluded: '+(x.countryMismatch||0)+' wrong country, '+(x.countryUnknown||0)+' country unknown, '+(x.languageMismatch||0)+' language conflict, '+(x.languageInsufficient||0)+' language unknown / insufficient. '+(data.cached?'Cached':'Retrieved')+' '+data.fetchedAt;
  if(data.warnings?.length)error=data.warnings.join(' ');
 }catch(e){error=e.message;resultNote=q.ids.length?'Search failed. Previous results retained; they belong to an earlier search.':'Search failed. No results substituted.'}
 finally{busy=false;refresh()}
}
document.querySelector('#research-form')?.addEventListener('submit',e=>{e.preventDefault();search()});document.querySelector('#next-page')?.addEventListener('click',()=>search(true));
async function importText(text,filename){if(busy)return;busy=true;error='';refresh();try{const data=await api('/api/import',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({csv:text,filename})});for(const c of data.creators)state.records[c.id]=c;q.source='imported';csvDraft='';resultNote=`${data.count} records imported / updated`;toast(resultNote)}catch(e){error=e.message}finally{busy=false;refresh()}}
document.querySelector('#csv-file')?.addEventListener('change',async e=>{const f=e.target.files[0];if(!f)return;if(f.size>1000000){error='Maximum CSV size is 1 MB.';return refresh()}await importText(await f.text(),f.name)});
document.querySelector('#csv-text')?.addEventListener('input',e=>{csvDraft=e.target.value});
document.querySelector('#csv-paste')?.addEventListener('click',()=>importText(document.querySelector('#csv-text').value,'Pasted CSV'));
document.querySelectorAll('[data-rdetail]').forEach(b=>b.onclick=()=>select(b.dataset.rdetail));
document.querySelectorAll('[data-rsave]').forEach(b=>b.onclick=()=>{ensure(b.dataset.rsave);refresh();toast('Saved to shortlist. No outreach sent.')});
document.querySelectorAll('[data-rweight]').forEach(i=>i.onchange=()=>{state.researchWeights[i.dataset.rweight]=Number(i.value);refresh();const d=document.querySelector('details');if(d)d.open=true});
document.querySelectorAll('[data-rcompare]').forEach(i=>i.onchange=()=>{if(i.checked&&comparison.length>=3){i.checked=false;return toast('Compare up to three creators.')}comparison=i.checked?[...comparison,i.dataset.rcompare]:comparison.filter(x=>x!==i.dataset.rcompare);refresh()});document.querySelector('#rcompare-show')?.addEventListener('click',()=>{showCompare=!showCompare;refresh()});
document.querySelector('#review-status')?.addEventListener('change',e=>{const p=ensure(e.target.dataset.id);p.review=e.target.value;if(p.review==='Rejected'){p.approved=false;p.status='Shortlisted'}refresh();toast('Review decision saved.')});document.querySelector('#review-notes')?.addEventListener('input',e=>{ensure(e.target.dataset.id).notes=e.target.value;save()});
document.querySelector('#export-one')?.addEventListener('click',e=>{ensure(e.target.dataset.id);save();exportShortlist(state,creators(),[e.target.dataset.id])});
document.querySelectorAll('[data-comments]').forEach(b=>b.onclick=async()=>{const id=b.dataset.comments;b.disabled=true;b.textContent='Loading public questions…';try{comments[id]=await api('/api/youtube/comments?videoId='+encodeURIComponent(id));if(!comments[id].comments.length)comments[id].note='No question-like comments found in this limited sample. '+comments[id].note;}catch(e){comments[id]={error:e.message}}render()});
document.querySelectorAll('[data-rdraft]').forEach(b=>b.onclick=()=>{const c=state.records[b.dataset.rdraft],p=ensure(c.id);if(p.draft&&!confirm('Replace the current draft?'))return;p.draft=`Subject: A Prenew collaboration idea\n\nHi ${c.name} team,\n\nWe found your channel while researching ${q.niche.toLowerCase()}. ${c.videos?.length?'Your video “'+c.videos[0].title+'” ('+c.videos[0].url+') is a starting point for our review.':'We would like to learn more about your recent PC-related content.'}\n\n${state.campaign.facts}\n\nAn idea to explore: ${angle(c,q)}\n\nWould this fit your content and audience? Please share your audience market information, availability and rates. We can agree on the details and sponsorship disclosure together.\n\nBest,\nPrenew marketing team\n\n[Review facts, watch the source content and replace sender details before use.]`;p.approved=false;p.status='Shortlisted';refresh();document.querySelector('details').open=true});
document.querySelector('#research-draft')?.addEventListener('input',e=>{const p=ensure(e.target.dataset.id);p.draft=e.target.value;p.approved=false;p.status='Shortlisted';save();const b=document.querySelector('[data-rapprove]');b.disabled=!p.draft.trim()||p.review==='Rejected';b.textContent='Approve draft'});
document.querySelectorAll('[data-rapprove]').forEach(b=>b.onclick=()=>{const p=ensure(b.dataset.rapprove);if(!p.draft.trim()||p.review==='Rejected')return;p.approved=true;p.status='Ready to Contact';refresh();toast('Approved for manual contact. Nothing sent.');document.querySelector('details').open=true});
}
